window.__ttsmArticleContent["d3115e9e707e"] = "<div>\n<p>Khoảng 11h20 ngày 24/9, tại đường Vành đai 3 trên cao, đoạn đối diện số 151 Nguyễn Xiển, xảy ra vụ tai nạn giao thông liên hoàn giữa 4 ô tô (biển kiểm soát 35A-674.XX, 29E-820.XX, 18A-435.XX và một xe con chưa rõ BKS).</p>\n<p>Sau khi nhận tin báo, Đội CSGT đường bộ số 7 (Phòng CSGT Công an Hà Nội) cử cán bộ tới hiện trường, phối hợp với lực lượng chức năng làm rõ nguyên nhân vụ tai nạn.</p>\n<figure><picture><!--[if IE 9]><video style=\"display: none;\"><![endif]--><!--[if IE 9]></video><![endif]--><img alt=\"Ảnh màn hình 2026 09 24 lúc 13.50.14.png\" src=\"https://static-images.vnncdn.net/vps_images_publish/000001/000003/2026/9/24/anh-man-hinh-2026-09-24-luc-135014-1608.png?width=0&amp;s=c41OOl5DG0hKj1e0nHFO_g\"/></picture>\n<figcaption>Hiện trường vụ tai nạn giao thông tại Vành đai 3 trên cao. Ảnh: H.H</figcaption>\n</figure>\n<p>Tại hiện trường, 3 chiếc ô tô bị hư hỏng, xe mang BKS 29E-820.XX màu đỏ bị nổ lốp sau, vỡ nát nhiều bộ phận và xoay ngược chiều trên đường.</p>\n<p>Được biết, vụ việc không gây thiệt hại về người; thiệt hại về tài sản đang được thống kê.</p>\n<div>\n<article><a href=\"https://vietnamnet.vn/bien-bao-vach-ke-dinh-khoang-cach-xuat-hien-tren-cau-nhat-tan-2558363.html\" title=\"Biển báo, vạch kẻ định khoảng cách xuất hiện trên cầu Nhật Tân\"><picture><img alt=\"Biển báo, vạch kẻ định khoảng cách xuất hiện trên cầu Nhật Tân\" src=\"https://static-images.vnncdn.net/vps_images_publish/000001/000003/2026/9/24/vach-khoang-cach-hieu1413-sao-chep-757.jpg?width=0&amp;s=b5_BPibEnSsAY8aTmJzKsQ\"/></picture></a>\n<div>\n<div><a href=\"https://vietnamnet.vn/bien-bao-vach-ke-dinh-khoang-cach-xuat-hien-tren-cau-nhat-tan-2558363.html\" title=\"Biển báo, vạch kẻ định khoảng cách xuất hiện trên cầu Nhật Tân\">Biển báo, vạch kẻ định khoảng cách xuất hiện trên cầu Nhật Tân</a></div>\n<div>Hệ thống biển báo và vạch sơn định khoảng cách đang được lắp đặt trên cầu Nhật Tân, Hà Nội, nhằm tăng cảnh báo và phòng ngừa tai nạn liên hoàn.</div>\n</div>\n</article>\n<article><a href=\"https://vietnamnet.vn/xe-khach-tong-lien-hoan-roi-lat-nghieng-2-nguoi-tu-vong-2558027.html\" title=\"Xe khách tông liên hoàn rồi lật nghiêng, 2 người tử vong\"><picture><img alt=\"Xe khách tông liên hoàn rồi lật nghiêng, 2 người tử vong\" src=\"https://static-images.vnncdn.net/vps_images_publish/000001/000003/2026/9/23/xe-khach-tong-lien-hoan-roi-lat-nghieng-2-nguoi-tu-vong-1429.jpg?width=0&amp;s=32wSLXGYhWHcSVm_QARZzQ\"/></picture></a>\n<div>\n<div><a href=\"https://vietnamnet.vn/xe-khach-tong-lien-hoan-roi-lat-nghieng-2-nguoi-tu-vong-2558027.html\" title=\"Xe khách tông liên hoàn rồi lật nghiêng, 2 người tử vong\">Xe khách tông liên hoàn rồi lật nghiêng, 2 người tử vong</a></div>\n<div>Ngày 23/9, Trạm CSGT Tuy Phước (Gia Lai) cho biết một vụ tai nạn giao thông liên hoàn đã xảy ra tại khu vực phường An Nhơn Bắc khiến 2 người tử vong.</div>\n</div>\n</article>\n<article><a href=\"https://vietnamnet.vn/5-o-to-bi-hu-hong-sau-tai-nan-lien-hoan-trong-dem-o-lam-dong-2557901.html\" title=\"5 ô tô bị hư hỏng sau tai nạn liên hoàn trong đêm ở Lâm Đồng\"><picture><img alt=\"5 ô tô bị hư hỏng sau tai nạn liên hoàn trong đêm ở Lâm Đồng\" src=\"https://static-images.vnncdn.net/vps_images_publish/000001/000003/2026/9/23/5-o-to-bi-hu-hong-sau-tai-nan-lien-hoan-trong-dem-o-lam-dong-1196.jpg?width=0&amp;s=Aj3C_KlFP2c_SzC3vmouhw\"/></picture></a>\n<div>\n<div><a href=\"https://vietnamnet.vn/5-o-to-bi-hu-hong-sau-tai-nan-lien-hoan-trong-dem-o-lam-dong-2557901.html\" title=\"5 ô tô bị hư hỏng sau tai nạn liên hoàn trong đêm ở Lâm Đồng\">5 ô tô bị hư hỏng sau tai nạn liên hoàn trong đêm ở Lâm Đồng</a></div>\n<div>Một vụ tai nạn liên hoàn đã xảy ra trên quốc lộ 14 (địa phận xã Quảng Tín, Lâm Đồng) khiến 5 ô tô bị hư hỏng nặng.</div>\n</div>\n</article>\n</div> <!-- BEGIN COMPONENT:: COMPONENT002778 -->\n<!-- END COMPONENT:: COMPONENT002778 -->\n</div>";
